/**
 * Generated by `bun run stored-shapes` (packages/hub/scripts/stored-shapes.ts)
 * from the types CawCo stores as JSON: never edited by hand. Each schema's
 * output is proved to be its type exactly in stored-shapes.proof.ts beside it.
 */
import { ARTIFACT_KINDS } from "@cawco/core/artifact-kinds";
import { HARNESSES, WIRE_PERMISSION_MODES } from "@cawco/core/harness/kinds";
import {
  PLAN_EDIT_KINDS,
  PLAN_STEP_PRIORITIES,
  PLAN_STEP_STATUSES,
} from "@cawco/core/plan";
import { STAGE_TOOLCHAINS } from "@cawco/core/stage";
import { z } from "zod";

const BrowserKeyShape = z.union([
  z.templateLiteral(["project:", z.string()]),
  z.templateLiteral(["machine:", z.string()]),
]);
export type BrowserKeyOutput = z.output<typeof BrowserKeyShape>;

const BrowserAskFrameShape = z.object({
  artifactId: z.string(),
  key: BrowserKeyShape,
  machineId: z.string(),
  origin: z.string(),
  reason: z.string(),
});
export type BrowserAskFrameOutput = z.output<typeof BrowserAskFrameShape>;

const BrowserHostKindShape = z.enum(["container", "local"]);
export type BrowserHostKindOutput = z.output<typeof BrowserHostKindShape>;

const PasskeyRelayCapabilityShape = z.object({
  hasBle: z.boolean(),
  hasVhci: z.boolean(),
});
export type PasskeyRelayCapabilityOutput = z.output<
  typeof PasskeyRelayCapabilityShape
>;

const BrowserStateShape = z.enum([
  "pulling",
  "building",
  "starting",
  "live",
  "stopping",
  "asleep",
  "failed",
]);
export type BrowserStateOutput = z.output<typeof BrowserStateShape>;

const ListedBrowserShape = z.object({
  host: BrowserHostKindShape,
  key: BrowserKeyShape,
  lastUsedAt: z.number(),
  machineId: z.string(),
  machineName: z.string(),
  name: z.string(),
  origin: z.string().optional(),
  passkeyRelay: PasskeyRelayCapabilityShape.optional(),
  progress: z
    .object({ done: z.number(), total: z.number(), what: z.literal("image") })
    .optional(),
  projectId: z.string().nullable(),
  state: BrowserStateShape,
  takeover: z
    .object({
      by: z.string(),
      requestId: z.string().nullable(),
      since: z.number(),
    })
    .nullable(),
  why: z.string().optional(),
});
export type ListedBrowserOutput = z.output<typeof ListedBrowserShape>;

const ArtifactKindShape = z.enum(ARTIFACT_KINDS);
export type ArtifactKindOutput = z.output<typeof ArtifactKindShape>;

const PreviewSourceShape = z.union([
  z.object({
    port: z.number(),
    path: z.string().optional(),
    stage: z.object({ dir: z.string(), file: z.string() }).optional(),
    serve: z.object({ command: z.string(), cwd: z.string() }).optional(),
    workspace: z.string().optional(),
  }),
  z.object({ dir: z.string(), path: z.string().optional() }),
  z.object({ page: z.string() }),
]);
export type PreviewSourceOutput = z.output<typeof PreviewSourceShape>;

const StageErrorKindShape = z.enum(["missing", "compile", "page"]);
export type StageErrorKindOutput = z.output<typeof StageErrorKindShape>;

const StageErrorShape = z.object({
  column: z.number().nullable(),
  file: z.string(),
  frame: z.string().nullable(),
  kind: StageErrorKindShape.optional(),
  line: z.number().nullable(),
  message: z.string(),
  sheets: z.array(z.string()),
});
export type StageErrorOutput = z.output<typeof StageErrorShape>;

const StageStatusShape = z.enum([
  "starting",
  "waking",
  "live",
  "error",
  "asleep",
]);
export type StageStatusOutput = z.output<typeof StageStatusShape>;

const StageStateOfShape = z.object({
  at: z.string(),
  dir: z.string(),
  errors: z.array(StageErrorShape),
  message: z.string().optional(),
  status: StageStatusShape,
});

const StageToolchainShape = z.enum(STAGE_TOOLCHAINS);
export type StageToolchainOutput = z.output<typeof StageToolchainShape>;

const SheetStageStateShape = StageStateOfShape.extend({
  runs: z.literal("sheet"),
  toolchain: StageToolchainShape,
});

const ServerStageStateShape = StageStateOfShape.extend({
  runs: z.literal("serve"),
});

const StageStateShape = z.union([SheetStageStateShape, ServerStageStateShape]);
export type StageStateOutput = z.output<typeof StageStateShape>;

const TailnetOriginShape = z.object({
  hosts: z.array(z.string()),
  origin: z.string(),
});
export type TailnetOriginOutput = z.output<typeof TailnetOriginShape>;

const PreviewFrameShape = z.object({
  artifact: z.object({
    ask: z.string().optional(),
    id: z.string(),
    kind: ArtifactKindShape,
    name: z.string(),
    title: z.string(),
  }),
  artifacts: z.array(z.string()).optional(),
  instanceId: z.string(),
  kind: z.literal("preview"),
  origin: z.string().optional(),
  port: z.number().optional(),
  project: z.string().optional(),
  revision: z.string(),
  show: z.string(),
  source: PreviewSourceShape.optional(),
  stage: StageStateShape.optional(),
  state: z.enum(["open", "closed"]),
  tailnet: TailnetOriginShape.optional(),
});
export type PreviewFrameOutput = z.output<typeof PreviewFrameShape>;

const ArtifactSessionFrameShape = z.object({
  ask: z
    .object({ browserAsk: BrowserAskFrameShape, requestId: z.string() })
    .nullable(),
  browser: ListedBrowserShape.nullable(),
  machines: z.array(
    z.object({
      hostname: z.string(),
      machineId: z.string(),
      online: z.boolean(),
      os: z.string(),
    })
  ),
  preview: PreviewFrameShape.nullable(),
  session: z
    .object({
      cwd: z.string(),
      id: z.string(),
      machineId: z.string(),
      projectId: z.string().nullable(),
      title: z.string().nullable(),
    })
    .nullable(),
  type: z.literal("artifact.session"),
  working: z.boolean(),
});
export type ArtifactSessionFrameOutput = z.output<
  typeof ArtifactSessionFrameShape
>;

const ArtifactSessionHeardShape = z.union([
  ArtifactSessionFrameShape,
  z.object({
    payload: z.union([
      z.object({
        error: z.string().optional(),
        kind: z.literal("control_result"),
        ok: z.boolean(),
        result: z.unknown().optional(),
      }),
      z.object({ kind: z.literal("error"), message: z.string() }),
    ]),
    requestId: z.string().optional(),
    verb: z.literal("frames"),
  }),
  z.object({ type: z.literal("heartbeat") }),
]);
export const ArtifactSessionHeardSchema = ArtifactSessionHeardShape;
export type ArtifactSessionHeardOutput = z.output<
  typeof ArtifactSessionHeardShape
>;

const CompactMethodShape = z.enum(["native", "summary", "whole"]);
export type CompactMethodOutput = z.output<typeof CompactMethodShape>;

const HarnessKindShape = z.enum(HARNESSES);
export const HarnessKindSchema = HarnessKindShape;
export type HarnessKindOutput = z.output<typeof HarnessKindShape>;

const CompactionShape = z.object({
  atLimit: CompactMethodShape,
  beforeMove: CompactMethodShape,
  fileRoom: z.number(),
  summarizer: z.object({ harness: HarnessKindShape, model: z.string() }),
});
export type CompactionOutput = z.output<typeof CompactionShape>;

const AtLimitShape = z.object({
  compaction: CompactionShape,
  move: z.boolean(),
  moveWholeUnderK: z.number(),
  staleAfterHours: z.number(),
  waitMinutes: z.number(),
});
export const AtLimitSchema = AtLimitShape;
export type AtLimitOutput = z.output<typeof AtLimitShape>;

const BesideShape = z.object({ projectId: z.string(), taskId: z.string() });
export const BesideSchema = BesideShape;
export type BesideOutput = z.output<typeof BesideShape>;

export const CalledArtifactShape = z.object({
  id: z.string(),
  kind: ArtifactKindShape.optional(),
  title: z.string().optional(),
});
export type CalledArtifactOutput = z.output<typeof CalledArtifactShape>;

const CommandRefusalShape = z.object({
  asked: z.unknown().optional(),
  reason: z.string(),
});
export const CommandRefusalSchema = CommandRefusalShape;
export type CommandRefusalOutput = z.output<typeof CommandRefusalShape>;

const ComposeTargetShape = z.object({
  anchor: z.union([
    z.object({ element: z.string() }),
    z.looseObject({ selector: z.string() }),
  ]),
  elements: z.array(z.unknown()),
});
export const ComposeTargetSchema = ComposeTargetShape;
export type ComposeTargetOutput = z.output<typeof ComposeTargetShape>;

const ConnectFaultShape = z.union([
  z.object({ kind: z.literal("refused"), reason: z.string() }),
  z.object({ kind: z.literal("expired") }),
]);
export type ConnectFaultOutput = z.output<typeof ConnectFaultShape>;

const ConnectStageShape = z.enum(["asking", "waiting", "done", "failed"]);

const ConnectSignInShape = z.object({
  expiresAt: z.number().optional(),
  fault: ConnectFaultShape.nullable(),
  stage: ConnectStageShape,
});
export const ConnectSignInSchema = ConnectSignInShape;
export type ConnectSignInOutput = z.output<typeof ConnectSignInShape>;

const ContinueSourceShape = z.object({
  cwd: z.string(),
  harness: HarnessKindShape,
  instanceId: z.string(),
  machineId: z.string(),
  model: z.string().optional(),
  title: z.string(),
});
export const ContinueSourceSchema = ContinueSourceShape;
export type ContinueSourceOutput = z.output<typeof ContinueSourceShape>;

const DraftCanvasShape = z.object({
  folded: z.boolean(),
  id: z.string(),
  name: z.string(),
  thumb: z.string().nullable(),
});
export type DraftCanvasOutput = z.output<typeof DraftCanvasShape>;

const PendingFileShape = z.object({
  as: z.enum(["image", "text"]).optional(),
  blob: z.instanceof(Blob).optional(),
  error: z.string().optional(),
  height: z.number().optional(),
  id: z.string(),
  mediaType: z.string(),
  name: z.string(),
  preview: z.string().optional(),
  progress: z.number(),
  ref: z.string().optional(),
  size: z.number(),
  width: z.number().optional(),
});
export type PendingFileOutput = z.output<typeof PendingFileShape>;

const StoredFileShape = PendingFileShape.pick({
  name: true,
  mediaType: true,
  size: true,
  ref: true,
}).extend({ blob: z.instanceof(Blob).optional() });
export type StoredFileOutput = z.output<typeof StoredFileShape>;

const PendingTextShape = z.object({
  content: z.string(),
  kind: z.literal("text"),
  name: z.string(),
});
export type PendingTextOutput = z.output<typeof PendingTextShape>;

const DraftRecordShape = z.object({
  canvas: DraftCanvasShape.nullable().optional(),
  files: z.array(StoredFileShape).optional(),
  images: z.array(
    z.object({
      blob: z.instanceof(Blob),
      mediaType: z.string(),
      name: z.string(),
    })
  ),
  sessionId: z.string(),
  size: z.number(),
  text: z.string(),
  texts: z.array(PendingTextShape),
  updatedAt: z.number(),
});
export const DraftRecordSchema = DraftRecordShape;
export type DraftRecordOutput = z.output<typeof DraftRecordShape>;

const KeptStateShape = z.object({
  state: z.string(),
  variant: z.string().nullable(),
});
export type KeptStateOutput = z.output<typeof KeptStateShape>;

const GraphKeptShape = z.object({
  ask: z.string(),
  front: z.string().nullable(),
  kept: z.record(z.string(), KeptStateShape),
});
export const GraphKeptSchema = GraphKeptShape;
export type GraphKeptOutput = z.output<typeof GraphKeptShape>;

const ForkSourceShape = z.object({
  at: z.string().optional(),
  cwd: z.string(),
  harness: HarnessKindShape,
  machineId: z.string(),
  resumes: z.literal(true).optional(),
  sessionId: z.string(),
});
export type ForkSourceOutput = z.output<typeof ForkSourceShape>;

const TextAttachmentShape = z.object({
  content: z.string(),
  kind: z.literal("text"),
  name: z.string(),
});
export type TextAttachmentOutput = z.output<typeof TextAttachmentShape>;

const FileAttachmentShape = z.object({
  kind: z.literal("file"),
  mediaType: z.string(),
  name: z.string(),
  ref: z.string(),
  size: z.number(),
});
export type FileAttachmentOutput = z.output<typeof FileAttachmentShape>;

const SendAttachmentShape = z.union([TextAttachmentShape, FileAttachmentShape]);
export type SendAttachmentOutput = z.output<typeof SendAttachmentShape>;

const UserAnswersShape = z.record(
  z.string(),
  z.union([z.string(), z.array(z.string())])
);
export type UserAnswersOutput = z.output<typeof UserAnswersShape>;

const UserQuestionShape = z.object({
  header: z.string(),
  multiSelect: z.boolean(),
  options: z.array(z.object({ label: z.string(), description: z.string() })),
  question: z.string(),
});
export type UserQuestionOutput = z.output<typeof UserQuestionShape>;

const UserQuestionAnsweredShape = z.object({
  annotations: z
    .record(
      z.string(),
      z.object({ notes: z.string().optional(), preview: z.string().optional() })
    )
    .optional(),
  answers: UserAnswersShape,
  outcome: z.literal("answered"),
  questions: z.array(UserQuestionShape),
  response: z.string().optional(),
});
export type UserQuestionAnsweredOutput = z.output<
  typeof UserQuestionAnsweredShape
>;

const UserQuestionDismissedShape = z.object({
  outcome: z.literal("dismissed"),
  questions: z.array(UserQuestionShape),
});
export type UserQuestionDismissedOutput = z.output<
  typeof UserQuestionDismissedShape
>;

const UserQuestionResultShape = z.union([
  UserQuestionAnsweredShape,
  UserQuestionDismissedShape,
]);
export type UserQuestionResultOutput = z.output<typeof UserQuestionResultShape>;

const NeutralContentBlockShape = z.union([
  z.object({ type: z.literal("text"), text: z.string() }),
  z.object({
    type: z.literal("thinking"),
    thinking: z.string(),
    signature: z.string().optional(),
  }),
  z.object({ type: z.literal("redacted_thinking") }),
  z.object({
    type: z.literal("tool_use"),
    id: z.string(),
    name: z.string(),
    input: z.record(z.string(), z.unknown()),
  }),
  z.object({
    type: z.literal("tool_result"),
    tool_use_id: z.string(),
    content: z.unknown(),
    is_error: z.boolean().optional(),
    structuredContent: z.record(z.string(), z.unknown()).optional(),
    questionResult: UserQuestionResultShape.optional(),
  }),
  z.object({
    type: z.literal("image"),
    source: z.union([
      z.object({
        type: z.literal("base64"),
        media_type: z.string(),
        data: z.string(),
      }),
      z.object({
        type: z.literal("url"),
        media_type: z.string(),
        url: z.string(),
      }),
    ]),
  }),
]);
export type NeutralContentBlockOutput = z.output<
  typeof NeutralContentBlockShape
>;

const HarnessNoteShape = z.object({
  body: z.string(),
  kind: z.enum(["task-notification", "system-reminder"]),
  status: z.string(),
  title: z.string(),
  toolUseId: z.string().optional(),
});
export type HarnessNoteOutput = z.output<typeof HarnessNoteShape>;

const NeutralOriginShape = z.union([
  z.object({ kind: z.literal("human") }),
  z.object({
    kind: z.literal("peer"),
    from: z.string().optional(),
    name: z.string().optional(),
    fromSession: z.string().optional(),
    body: z.string().optional(),
  }),
  z.object({
    kind: z.literal("system"),
    line: z.string().optional(),
    live: z.enum(["running", "ended"]).optional(),
    name: z.string().optional(),
  }),
]);
export type NeutralOriginOutput = z.output<typeof NeutralOriginShape>;

const NeutralUserMessageShape = z.object({
  compactSummary: z.literal(true).optional(),
  keepAlive: z.literal(true).optional(),
  message: z.object({
    role: z.literal("user"),
    content: z.union([z.string(), z.array(NeutralContentBlockShape)]),
    harnessNote: HarnessNoteShape.optional(),
  }),
  origin: NeutralOriginShape.optional(),
  parent_tool_use_id: z.string().nullable().optional(),
  raw: z.unknown().optional(),
  reminder: z.string().optional(),
  replaces: z.string().optional(),
  session_id: z.string().optional(),
  shouldQuery: z.boolean().optional(),
  timestamp: z.string().optional(),
  type: z.literal("user"),
  uuid: z.string().optional(),
});
export type NeutralUserMessageOutput = z.output<typeof NeutralUserMessageShape>;

const SentMessageShape = NeutralUserMessageShape.extend({
  origin: NeutralOriginShape,
  uuid: z.string(),
});
export type SentMessageOutput = z.output<typeof SentMessageShape>;

const SendPayloadShape = z.object({
  attachments: z.array(SendAttachmentShape).optional(),
  delivery: z.string().optional(),
  from: z.string().optional(),
  images: z
    .array(z.object({ mediaType: z.string(), data: z.string() }))
    .optional(),
  instanceId: z.string(),
  message: SentMessageShape,
  provenance: z
    .object({
      clientId: z.string().optional(),
      presenceId: z.string().optional(),
    })
    .optional(),
});
export type SendPayloadOutput = z.output<typeof SendPayloadShape>;

const SendExtrasShape = SendPayloadShape.pick({
  attachments: true,
  images: true,
});
export type SendExtrasOutput = z.output<typeof SendExtrasShape>;

const SpawnPrefillShape = z.object({
  cwd: z.string().optional(),
  fork: ForkSourceShape.optional(),
  machineId: z.string().optional(),
  projectId: z.string().optional(),
  prompt: z.object({ text: z.string(), extras: SendExtrasShape }).optional(),
  spinOff: z.boolean().optional(),
});
export type SpawnPrefillOutput = z.output<typeof SpawnPrefillShape>;

const KeptFormShape = z.object({
  open: z.boolean(),
  prefill: SpawnPrefillShape.optional(),
  shown: z.string().nullable(),
});
export const KeptFormSchema = KeptFormShape;
export type KeptFormOutput = z.output<typeof KeptFormShape>;

const PairingStageShape = z.union([
  z.object({
    kind: z.literal("waiting"),
    expiresAt: z.number(),
    userCode: z.string(),
    verificationUriComplete: z.string(),
  }),
  z.object({ kind: z.literal("failed"), message: z.string() }),
  z.object({ kind: z.literal("idle") }),
  z.object({ kind: z.literal("asking") }),
  z.object({ kind: z.enum(["denied", "expired"]) }),
]);
export type PairingStageOutput = z.output<typeof PairingStageShape>;

const KeptPairingShape = z.object({
  deviceCode: z.string().optional(),
  interval: z.number().optional(),
  stage: PairingStageShape,
});
export const KeptPairingSchema = KeptPairingShape;
export type KeptPairingOutput = z.output<typeof KeptPairingShape>;

const KeptSendShape = z.object({
  at: z.number(),
  commandId: z.string(),
  extras: SendExtrasShape,
  instanceId: z.string(),
  machineId: z.string(),
  refused: z.object({ at: z.number(), reason: z.string() }).optional(),
  replaces: z.string().optional(),
  text: z.string(),
});
export const KeptSendSchema = KeptSendShape;
export type KeptSendOutput = z.output<typeof KeptSendShape>;

const RefusalShape = z.object({
  act: z.enum(["install", "cancel"]),
  reason: z.string(),
});
