const StopPhaseShape = z.enum([
  "none",
  "list",
  "armed",
  "stopping",
  "fail",
  "ending",
  "done",
]);

const PlaceProjectShape = z.object({ id: z.string(), name: z.string() });
export type PlaceProjectOutput = z.output<typeof PlaceProjectShape>;

const RunningSessionShape = z.object({
  cwd: z.string(),
  id: z.string(),
  machineId: z.string(),
  offline: z.boolean(),
  parentId: z.string().nullable(),
  title: z.string().nullable(),
});
export type RunningSessionOutput = z.output<typeof RunningSessionShape>;

const StopRowShape = z.object({
  arrived: z.boolean(),
  departed: z.boolean(),
  error: z.string().nullable(),
  gone: z.boolean(),
  owed: z.boolean(),
  s: RunningSessionShape,
  state: z.enum(["running", "away", "stopping", "stopped", "failed", "kept"]),
  view: z.object({
    href: z.string().optional(),
    kind: z.enum(["attempt", "delegate"]).optional(),
    title: z.string().optional(),
  }),
});
export type StopRowOutput = z.output<typeof StopRowShape>;

const StopJobShape = z.object({
  at: z.string(),
  fromDisk: z.boolean(),
  kind: StopKindShape,
  off: z.boolean(),
  open: z.boolean(),
  phase: StopPhaseShape,
  picked: z.array(z.string()),
  places: z.array(
    z.object({
      machineId: z.string(),
      path: z.string(),
      within: z.array(PlaceProjectShape),
    })
  ),
  pressedAt: z.number(),
  projectId: z.string(),
  projectName: z.string(),
  refusal: z.string().nullable(),
  rows: z.array(StopRowShape),
  total: z.number(),
});
